using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using Autodesk.AutoCAD.Runtime;using Autodesk.AutoCAD.DatabaseServices;using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
public class UgoDetail {const string Folder=@"C:\Users\user\Desktop\02_Справочники_CAD_Revit\odnolineyka\_Разработка\ugo";const string FileName=@"\\Server\DropBox\Работа server\4. Техдепартамент\4.1. Проекты\098 Ташкент-КТ\5 ПИР\5.5_Том 4 Пост охраны\01_ELF-D1-03-ЭОМ\01_Титул.DWG";
static void Texts(Entity e,Transaction tr,List<string> texts,int level=0){if(level>3)return;if(e is MText m)texts.Add(m.Text);else if(e is DBText t)texts.Add(t.TextString);else if(e is BlockReference br)foreach(ObjectId id in (BlockTableRecord)tr.GetObject(br.BlockTableRecord,OpenMode.ForRead)){if(tr.GetObject(id,OpenMode.ForRead) is Entity child)Texts(child,tr,texts,level+1);}else if(e is Table tab)for(int r=0;r<tab.Rows.Count;r++)for(int c=0;c<tab.Columns.Count;c++)texts.Add(tab.Cells[r,c].TextString);}
[CommandMethod("CODEXUGODETAIL",CommandFlags.Session)]public void Run(){try{using(var db=new Database(false,true)){db.ReadDwgFile(FileName,FileOpenMode.OpenForReadAndAllShare,false,null);db.CloseInput(true);using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var model=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);var items=new List<object>();foreach(ObjectId id in model){if(!(tr.GetObject(id,OpenMode.ForRead) is Entity e))continue;Extents3d ex;try{ex=e.GeometricExtents;}catch{continue;}if(ex.MinPoint.X<1060 || ex.MaxPoint.X>1260 || ex.MaxPoint.Y>0 || ex.MinPoint.Y< -330)continue;var texts=new List<string>();Texts(e,tr,texts);items.Add(new{Handle=e.Handle.ToString(),Type=e.GetType().Name,Layer=e.Layer,Min=new[]{ex.MinPoint.X,ex.MinPoint.Y},Max=new[]{ex.MaxPoint.X,ex.MaxPoint.Y},Texts=texts});}File.WriteAllText(Path.Combine(Folder,"detail.json"),JsonSerializer.Serialize(items,new JsonSerializerOptions{WriteIndented=true}));}}}catch(System.Exception ex){File.WriteAllText(Path.Combine(Folder,"detail_error.txt"),ex.ToString());}}
}